dict(toc='Article 21: foundation, livelihood, shelter, health, menstrual health', id=62, title='ARTICLE 21 · GOLDEN TRIANGLE · LIVELIHOOD · HEALTH · MENSTRUAL HEALTH', part=0, icon='scale', prio='L',
 pyq=NOPYQ + 'pp. 5-7',
 simple='Arts 14, 19 and 21 are the Golden Triangle. Art 21 moved from procedure established by law (Gopalan) to fair, just and reasonable procedure (Maneka), and from a negative duty to positive duties: livelihood (Olga Tellis), health, menstrual health. A "canopy" of rights.',
 nodes=[
 sec('FOUNDATION', 'b'),
 bx('pk', '<b>Golden Triangle:</b> Arts <b>14, 19, 21</b>. Even if other Part III rights were removed, much protection could be deduced from these three (equality, freedom, life and personal liberty).'),
 t('<b>Text and early reading</b>',
   '"No person shall be deprived of his <b>life or personal liberty</b> except according to <b>procedure established by law</b>"',
   'first read as protection from <b>executive</b>, not <b>legislative</b>, tyranny; the law\'s <b>reasonableness</b> is not mentioned'),
 tl(('1950', '<b>A. K. Gopalan:</b> narrow reading of personal liberty and procedure established by law'),
    ('1978', '<b>Maneka Gandhi:</b> procedure must be <b>fair, just and reasonable</b>, not arbitrary or oppressive'),
    ('Later', 'livelihood, health, shelter, privacy, dignity, environment, access to justice')),
 t('<b>Negative to positive obligation</b>',
   'life once meant only physical existence; the State\'s duty has grown from <b>not interfering</b> to <b>protecting and preserving life</b> (health, shelter, education, environment)',
   '<b>rights read into 21:</b> dignity, livelihood, shelter · health, emergency aid, menstrual health · clean environment and climate · privacy, autonomy, reputation · fair and speedy trial, legal aid · protection from custodial violence and inhuman prison conditions · peaceful sleep',
   'Art 21 is a <b>canopy of rights</b>'),
 sec('LIVELIHOOD AND SHELTER', 'r'),
 bx('ye', '<b>Olga Tellis v. Bombay Municipal Corporation (1985):</b> pavement and slum dwellers evicted as encroachers. Held: <b>right to life includes right to livelihood</b>; eviction needs <b>fair and lawful procedure</b>. It did <b>not</b> create an absolute right to alternative housing. Linked <b>Part III with Part IV</b>, bridging civil-political and socio-economic rights.'),
 sec('HEALTH AND MENSTRUAL HEALTH', 'g'),
 t('<b>Right to health</b>',
   'access to <b>healthcare and emergency medical aid</b> is part of life and dignity',
   'positive duty, extent depends on <b>constitutional standards, laws and resources</b>'),
 t('<b>Right to menstrual health</b>',
   'manage menstruation <b>safely, affordably, with dignity</b>: clean toilets, sanitary products, medical support, no stigma',
   'linked to <b>life, dignity, health, education</b>; SC stressed sanitary products, private clean toilets and safe disposal in <b>schools</b>',
   '<b>mandatory menstrual leave:</b> the Court left it to <b>policy</b>, not a nationwide judicial order'),
 tb(['Policy dilemma', 'Practical solutions'],
    ['severe pain (e.g. endometriosis): no one should be forced to work through it', 'flexible hours, work from home'],
    ['mandatory employer-paid leave may cause <b>hiring bias</b>', 'clean rest rooms, private sanitation, pain relief'],
    ['', 'school sanitary products, running water, safe disposal']),
 ],
 recall=[('Golden Triangle', 'Arts 14, 19, 21'), ('Gopalan vs Maneka', 'narrow vs fair, just, reasonable'), ('Olga Tellis 1985', 'livelihood part of life; no absolute right to alternative housing'), ('Art 21 role shift', 'negative to positive obligation'), ('Menstrual leave', 'left to policy by the SC')]),

